    ['System of record','Sistem utama yang diakui sebagai sumber data resmi; contoh ERP atau EPM.'],['ERP','Enterprise Resource Planning; sumber transaksi dan GL seperti SAP atau Oracle.'],['EPM','Enterprise Performance Management; dapat menangani konsolidasi akuntansi dan financial close.'],['GL','General Ledger: buku besar dengan detail akun dan jurnal.'],['TB','Trial Balance: daftar saldo akun, idealnya menyeimbangkan debet dan kredit sesuai basis data.'],['COA','Chart of Accounts: struktur kode dan nama akun.'],['Fact table','Tabel detail transaksi/saldo yang bertambah dari waktu ke waktu.'],['Dimension table','Tabel referensi seperti entitas, COA, periode, lokasi, atau hierarchy.'],['Grain','Tingkat detail unik dari suatu baris data; misalnya satu account–entity–period–currency.'],['Dataset','Sekumpulan data yang dimuat atau terhubung ke tabel.'],['Schema','Struktur kolom dan tipe data dari tabel.'],['Wdata query','Ekstraksi, join, filter, perhitungan, dan aggregasi dari sumber Wdata/Spreadsheet.'],['Query parameter','Nilai yang dimasukkan saat query dijalankan, misalnya fiscal year atau entity.'],['View','Visualisasi query: flat table, pivot, atau chart.'],['Join','Penggabungan tabel berdasarkan kolom kunci; left join biasa dipakai untuk mempertahankan semua fact rows.'],['Cardinality','Relasi jumlah baris antar tabel, seperti one-to-one atau one-to-many.'],['Mapping','Pemetaan akun/entitas dari kode sumber ke struktur pelaporan.'],['Mapping group','Aturan pemetaan yang dikelola di Data Prep.'],['Pipeline','Urutan transformasi di Data Prep untuk mengolah input menjadi output standar.'],['Chain','Workflow automasi yang menghubungkan trigger, commands dan keluaran.'],['Command','Satu aksi dalam Chain seperti Run Query, Import File into Table, atau Refresh Connection.'],['Connector','Integrasi yang menyediakan command untuk sumber data atau Workiva.'],['CloudRunner','Runner untuk sistem online/cloud; dijalankan dalam infrastruktur Workiva.'],['GroundRunner','Runner khusus untuk sistem on-prem/private, dipasang dalam infrastruktur organisasi.'],['Runtime inputs','Parameter yang diminta ketika sebuah Chain dijalankan.'],['Integration user','Akun khusus untuk integrasi API/connector agar akses dan audit terpisah dari user biasa.'],['OAuth2 grant','Mekanisme autentikasi API Workiva memakai kredensial terotorisasi.'],['Incoming connection','Koneksi yang mengambil data ke sebuah Workiva spreadsheet atau dokumen.'],['Outgoing connection','Koneksi yang mengirim data dari Workiva spreadsheet ke Wdata table.'],['Data lineage','Asal-usul dan jalur transformasi data hingga menjadi angka laporan.'],['Reconciliation','Pencocokan totals/records antara sumber dan keluaran untuk mendeteksi selisih.'],['Intercompany elimination','Penghapusan transaksi/saldo antar entitas grup sesuai aturan konsolidasi akuntansi.'],['Exception','Baris atau kondisi yang gagal aturan pemeriksaan, perlu investigasi.'],['Tie-out','Pemeriksaan kesesuaian angka di laporan terhadap data sumber atau working paper.'],['Sign-off','Persetujuan/review yang dicatat sesuai kebijakan organisasi.'],['SOX','Sarbanes–Oxley Act; regulasi kontrol internal pelaporan keuangan di AS.'],['GRC','Governance, Risk and Compliance; proses risiko, kontrol, testing dan evidence.'],['XBRL','eXtensible Business Reporting Language untuk pelaporan data terstruktur.'],['Process task','Penugasan, review/approval dan timeline bisnis di Workiva; berbeda dari Chain commands.']
