const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=(key,label)=>{const v=W.sources[key];return `<a class="textlink" target="_blank" rel="noopener noreferrer" href="${v[1]}">${esc(label||v[0])} ↗</a>`};
const mark=(id)=>`<div class="notice-sign">Rujukan: ${source(id)}</div>`;
const eyebrow=(index,label)=>`<div class="eyebrow">CHAPTER ${String(index).padStart(2,'0')} · ${label}</div>`;
const intro=(n,head,description)=>`${eyebrow(n,'WORKIVA STUDY NOTES')}<h1>${head}</h1><p class="page-lead">${description}</p>`;
const callout=(head,txt,type='')=>`<div class="callout ${type}"><strong>${head}</strong><p>${txt}</p></div>`;
const card=(inner,extra='')=>`<div class="card ${extra}">${inner}</div>`;
const subhead=(head,small='')=>`<div class="section-title"><h2>${head}</h2>${small?`<p>${small}</p>`:''}</div>`;
const points=arr=>`<ul class="detail-list">${arr.map(i=>`<li>${i}</li>`).join('')}</ul>`;
const numbered=arr=>`<ol class="step-list">${arr.map(i=>`<li><div>${i}</div></li>`).join('')}</ol>`;
const imgCard=(id)=>{let o=W.images.find(x=>x.id===id);return `<div class="card figure"><div class="figure-image" role="button" tabindex="0" data-img="${id}" aria-label="Perbesar ${esc(o.name)}"><img loading="lazy" alt="${esc(o.name)}" src="${o.src}" onerror="this.style.display='none';this.parentElement.querySelector('.image-fallback').hidden=false"><div class="image-fallback" hidden><span>▣</span><b>Screenshot resmi Workiva</b><p>Gambar memerlukan akses internet atau kebijakan hotlink. Buka sumber aslinya di bawah.</p></div></div><div class="figure-caption"><h3>${esc(o.name)}</h3><p>${esc(o.desc)}</p><div class="figure-action"><button data-img="${id}">Perbesar screenshot ↗</button><a href="${W.sources[o.source][1]}" target="_blank" rel="noopener">Dokumentasi sumber ↗</a></div></div></div>`};
const linkPage=(id,text)=>`<a class="topic-link" href="#${id}">${text} ↗</a>`;
const doneBox=(id,label)=>`<label class="check-item" data-check-label="${id}"><input type="checkbox" data-check="${id}" aria-label="Tandai selesai: ${esc(label)}"><span>${label}</span></label>`;
function nav(){let s=''; W.sections.forEach((item,i)=>{if(i===0||i===2||i===5||i===8||i===11)s+=`<div class="nav-group-label">${({0:'FOUNDATION',2:'PRODUCT DEEP DIVE',5:'FINANCE & ASSURANCE',8:'PRACTICE & PRESENT',11:'REFERENCE'})[i]}</div>`;s+=`<button class="nav-link" data-route="${item[0]}"><span class="nav-icon">${item[2]}</span><span>${item[1]}</span>${i===0?'<span class="nav-tag">START</span>':''}</button>`});$('#side-nav').innerHTML=s;}
const getRoute=()=>{const candidate=location.hash.slice(1).split('?')[0].replace(/-detail-\d+$/, '');return W.sections.some(s=>s[0]===candidate)?candidate:'overview'};
function pageOverview(){return `<div class="page page-wide"><div class="hero"><div class="hero-content"><div class="hero-kicker">THE CONNECTED DATA PLAYBOOK · INDONESIA</div><h1>Understand the flow.<br><em>Trust the numbers.</em></h1><p>Field guide interaktif untuk memahami Workiva dari sisi Wdata, Chains, Data Prep, audit data, dan financial reporting. Disusun dari dokumentasi publik dan contoh latihan sintetis.</p><div class="hero-actions"><a href="#architecture" class="btn btn-primary">Mulai dari workflow →</a><a href="#media" class="btn btn-dark-outline">▣ Lihat UI asli Workiva</a></div><div class="hero-meta"><span>✓ 12 topik terstruktur</span><span>◉ Interactive practice</span><span>▣ Screenshot & video</span></div></div><div class="hero-visual"><div class="mini-canvas"><div class="mini-top"><span></span><span></span><span></span></div><div class="mini-node-row"><div class="mini-node"><b>⌁</b>ERP / EPM</div><div class="mini-arrow">→</div><div class="mini-node"><b>◇</b>CHAINS</div><div class="mini-arrow">→</div><div class="mini-node"><b>▤</b>WDATA</div></div><div class="mini-bottom"><i></i><i></i><i></i><i></i></div><div style="font-size:9px;color:#799baf;margin-top:10px">Data loaded · Quality checks passed · Reporting synced</div></div></div></div>
  <div class="grid grid-4 mt-24"><div class="card stat-card"><span class="stat-icon">◇</span><small>CORE COMPONENTS</small><strong>05</strong><p>Wdata, Chains, Data Prep, Sheets, Reports</p></div><div class="card stat-card"><span class="stat-icon">▤</span><small>LEARNING MODULES</small><strong>12</strong><p>Fondasi sampai persiapan PGL</p></div><div class="card stat-card"><span class="stat-icon">▣</span><small>AUTHENTIC UI ASSETS</small><strong>08</strong><p>Screenshot resmi dari Help Center</p></div><div class="card stat-card"><span class="stat-icon">◉</span><small>INTERACTIVE TOOLS</small><strong>03</strong><p>Query, Chain run dan quiz</p></div></div>
  ${subhead('The big picture','Dari sumber data sampai angka laporan')}
  ${card(`<div class="card-pad"><div class="flow-track">${W.flow.map((f,i)=>`${i?'<div class="flow-chevron">›</div>':''}<button class="flow-stage ${i===0?'active':''}" data-flow="${i}"><span class="number">0${i+1}</span><strong>${f.short}</strong><small>${f.head}</small></button>`).join('')}</div><div id="flow-explain" class="flow-explain"></div></div>`)}
  ${callout('Batasan penting: “consolidate data” ≠ “accounting consolidation”','Wdata menggabungkan dan menganalisis data dari berbagai sumber. Eliminasi intercompany, translasi FX, ownership, NCI dan jurnal konsolidasi harus mengikuti standar akuntansi dan proses yang didesain—sering dilakukan di ERP/EPM atau proses tersendiri. Jangan menyamakan kedua istilah tersebut.')}
  ${subhead('The wider Workiva ecosystem','Produk lain yang perlu kamu kenali')}
  <div class="grid grid-4"><div class="card schema-card"><span class="small-top">PLATFORM CORE</span><h3>Workspaces & permissions</h3><p>File management, roles, access, change history, collaboration, comments, review, and tasks.</p></div><div class="card schema-card"><span class="small-top">CONNECTED OUTPUT</span><h3>Documents & presentations</h3><p>Spreadsheets, linked data, connected narrative, review and controlled publication.</p></div><div class="card schema-card"><span class="small-top">ASSURANCE</span><h3>GRC & audit</h3><p>Risks, controls, testing, exceptions, evidence, reporting and audit collaboration, as licensed/configured.</p></div><div class="card schema-card"><span class="small-top">SPECIALIZED SOLUTIONS</span><h3>SEC, statutory & XBRL</h3><p>Regulatory disclosures, structured tagging, certifications and filings when the relevant solution is enabled. ${source('sec','Learn more')}</p></div></div>
  ${subhead('Learning modules','Pilih topik sesuai kebutuhan')}
  <div class="grid grid-3">${W.sections.slice(1,10).map((m,i)=>`<a class="card module-card" href="#${m[0]}"><div class="module-index">MODULE ${String(i+1).padStart(2,'0')}</div><h3>${m[1]}</h3><p>${m[4]}</p><span class="module-link">Explore module ↗</span></a>`).join('')}</div>
  ${subhead('Suggested learning route','Prioritas sebelum sharing hari Jumat')}
  <div class="grid grid-3"><div class="card card-pad"><span class="pill teal">LEVEL 01</span><h3 class="mt-12">Foundation · 30 menit</h3><p class="text-small">Pahami aliran data, fact/dimension, query dan output.</p>${points(['End-to-end workflow','Wdata Tables & Queries','Spreadsheets & linked reporting'])}</div><div class="card card-pad"><span class="pill violet">LEVEL 02</span><h3 class="mt-12">Technical · 45 menit</h3><p class="text-small">Fokus orkestrasi dan kontrol kualitas.</p>${points(['Connectors, runners, chain commands','Data Prep & mapping','Hands-on lab'])}</div><div class="card card-pad"><span class="pill orange">LEVEL 03</span><h3 class="mt-12">PGL ready · 20 menit</h3><p class="text-small">Siapkan penjelasan dan jawaban pertanyaan.</p>${points(['UI screenshot/video walkthrough','Audit & consolidation pitfalls','12-minute presenter kit'])}</div></div>
  ${subhead('What you should be able to explain')}
  <div class="grid grid-2">${doneBox('obj1','Menjelaskan perbedaan Wdata, Chains, dan Data Prep.')}${doneBox('obj2','Memetakan perjalanan TB dari ERP ke final financial report.')}${doneBox('obj3','Menjelaskan fact, dimension, join, parameter, dan query.')}${doneBox('obj4','Menjelaskan kebutuhan audit evidence dan reconciliation.')}${doneBox('obj5','Menunjukkan UI Workiva yang sesuai dari referensi publik.')}${doneBox('obj6','Membawakan sesi 12 menit dengan narasi yang rapi.')}</div>
  <p class="disclaimer">Catatan: Website ini bukan akses ke Workiva asli. Semua demo, data, dan angka adalah simulasi edukasi. Screenshot asli dimuat dari situs resmi Workiva jika tersedia koneksi internet.</p></div>`}
function pageArchitecture(){return `<div class="page">${intro(1,'End-to-end data workflow','Gambaran teknis yang perlu kamu kuasai sebelum menjelaskan tool satu per satu: data berasal dari mana, diproses oleh siapa, diterima di mana, dan bagaimana hasilnya diaudit.')}
  ${card(`<div class="card-pad"><span class="pill teal">CLICK EACH STAGE</span><div class="flow-track">${W.flow.map((f,i)=>`${i?'<div class="flow-chevron">›</div>':''}<button class="flow-stage ${i===0?'active':''}" data-flow="${i}"><span class="number">0${i+1}</span><strong>${f.short}</strong><small>${f.head}</small></button>`).join('')}</div><div id="flow-explain" class="flow-explain"></div></div>`)}
  ${subhead('Contoh journey: monthly TB reporting')}
  <div class="grid grid-2"><div class="card card-pad"><h3>Sebelum masuk Workiva</h3>${numbered(['Client menutup buku periode <b>2026-10</b> di ERP/EPM.','Tim data mengekstrak TB untuk <b>entitas dan currency</b> yang disepakati.','Data owner menyetujui extract, cut-off, dan versi sumber.'])}</div><div class="card card-pad"><h3>Di Workiva dan output</h3>${numbered(['Chain mengambil CSV/API, melakukan validasi, lalu mengisi <b>Wdata fact TB</b>.','Query menggabungkan TB dengan <b>account & entity mapping</b>.','Spreadsheet menyajikan rollup; linked reports di-refresh dan <b>direview</b>.'])}</div></div>
  ${subhead('The control points that matter')}
  <div class="table-wrap"><table><thead><tr><th>Checkpoint</th><th>Pertanyaan kontrol</th><th>Contoh evidence</th></tr></thead><tbody><tr><td>Source extraction</td><td>Apakah semua entity, account, period tercakup?</td><td>Export manifest; control total; batch ID</td></tr><tr><td>Transformation</td><td>Apakah data type, sign, currency dan mapping benar?</td><td>Mapping version; unmapped report; validation log</td></tr><tr><td>Wdata loading</td><td>Jumlah records dan total saldo sama dengan input?</td><td>Run log; dataset tag; reconciliation</td></tr><tr><td>Query aggregation</td><td>Apakah join menyimpan seluruh baris dan bebas duplikasi?</td><td>Join checks; count before/after; exception listing</td></tr><tr><td>Report refresh</td><td>Apakah spreadsheet dan linked document memakai versi terkini?</td><td>Timestamp; source link; approval/sign-off</td></tr></tbody></table></div>
  ${callout('Catatan audit','Audit trail dari platform membantu keterlacakan, tetapi bukan pengganti prosedur audit. Data lineage, tie-out, bukti sumber, penilaian exception, dan sign-off tetap diperlukan.')}
  ${subhead('Jalur alternatif tergantung implementasi')}<div class="grid grid-2"><div class="card card-pad"><span class="pill">CSV-FIRST</span><h3 class="mt-12">Manual / semi-automated</h3><p>ERP export → CSV → Wdata Table → Query → Spreadsheet → Report. Cocok untuk sumber yang belum terintegrasi otomatis.</p></div><div class="card card-pad"><span class="pill teal">INTEGRATED</span><h3 class="mt-12">Automated</h3><p>ERP/API → Chain → (Data Prep) → Wdata → Query → Refresh connections → Reporting. Cocok untuk proses berkala dan banyak data.</p></div></div>
  <div class="mt-24">${mark('intro')}${mark('api')}</div>${doneBox('arch','Saya bisa menjelaskan enam tahap perjalanan data dan titik kontrolnya.')}</div>`}
function pageWdata(){return `<div class="page">${intro(2,'Wdata: from raw to report-ready','Wdata adalah lapisan data Workiva: menyimpan dataset dalam tables, menggabungkannya melalui queries, dan menyajikan hasil melalui views atau connections.')}
  <div class="grid grid-3"><div class="card schema-card"><span class="small-top">01 · STRUCTURE</span><h3>Tables</h3><p>Tempat menampung raw/curated data. Fact = saldo/transaksi; Dimension = entity, account, fiscal period, mapping.</p></div><div class="card schema-card"><span class="small-top">02 · LOGIC</span><h3>Queries</h3><p>Menggabungkan, memfilter, menghitung, dan mengelompokkan data via Query Builder atau SQL Editor.</p></div><div class="card schema-card"><span class="small-top">03 · EXPLORATION</span><h3>Views</h3><p>Menampilkan query sebagai flat table, pivot atau chart untuk melihat pola serta exception.</p></div></div>
  ${subhead('Fact vs dimension tables')}
  <div class="grid grid-2"><div class="card card-pad"><span class="pill teal">FACT · F_TB</span><h3 class="mt-12">Saldo per akun, entitas & periode</h3><div class="table-wrap"><table><thead><tr><th>entity_id</th><th>account_id</th><th>period</th><th class="td-number">amount</th></tr></thead><tbody><tr><td>E01</td><td>1100</td><td>2026-10</td><td class="td-number">1,200</td></tr><tr><td>E01</td><td>4100</td><td>2026-10</td><td class="td-number">-2,100</td></tr><tr><td>E02</td><td>1100</td><td>2026-10</td><td class="td-number">1,000</td></tr></tbody></table></div><p class="text-small mt-12">Grain ilustratif: satu account × entity × period × source version. Definisikan sign convention dan unit.</p></div><div class="card card-pad"><span class="pill violet">DIMENSION · D_ACCOUNT</span><h3 class="mt-12">Mapping akun ke reporting line</h3><div class="table-wrap"><table><thead><tr><th>account_id</th><th>account_name</th><th>reporting_line</th></tr></thead><tbody><tr><td>1100</td><td>Cash</td><td>Cash & equivalents</td></tr><tr><td>4100</td><td>Revenue</td><td>Revenue</td></tr><tr><td>5100</td><td>Expenses</td><td>Operating expenses</td></tr></tbody></table></div><p class="text-small mt-12">Dimension bisa berubah saat COA atau struktur pelaporan klien berubah; perlu kontrol versi.</p></div></div>
  ${subhead('Hands-on: buat Wdata table')}
  ${numbered(['Masuk ke <b>Wdata Home → Create → Table</b>. Beri nama yang mencerminkan grain, periode, dan tujuan.','Pilih <b>Fact</b> untuk TB/jurnal atau <b>Dimension</b> untuk master mapping.','Gunakan <b>Add Columns from source → Upload File</b> untuk mengimpor schema dari CSV/TSV.','Review <b>Display Name, Column ID, Type</b> satu per satu. Pastikan amount adalah numeric; period dan tanggal konsisten.','Klik <b>Create Table</b>, lalu tambahkan dataset dari file atau incoming source. Tambahkan tag, misalnya <code>period</code>, <code>entity</code>, <code>version</code>.','Cek jumlah baris, column schema dan nominal agregat; simpan source extract dan catatan rekonsiliasi.'])}
  <div class="grid grid-2 mt-24">${imgCard('table-schema')}${imgCard('table-type')}</div>
  ${subhead('Hands-on: buat query TB + account mapping')}
  ${numbered(['Di Wdata Home pilih <b>Create → Query</b>, tambah tabel dari panel Sources.','Tambahkan <b>F_TB</b>, <b>D_ACCOUNT</b> dan, bila perlu, <b>D_ENTITY</b>.','Pada <b>Relationships</b>, hubungkan <code>F_TB.account_id = D_ACCOUNT.account_id</code> memakai <b>Left Join</b> untuk mempertahankan baris TB yang belum ter-mapping.','Di <b>Fields</b>, pilih entity, period, account dan reporting_line; bila dibutuhkan tambahkan calculated fields/aggregation.','Di <b>Filters</b>, set periode dan entitas. Gunakan <b>parameters</b> untuk query yang dipakai ulang tiap bulan.','Jalankan <b>Run Query</b>, periksa total, count, unmapped, duplicate join, lalu <b>Save</b> dan hubungkan ke Spreadsheet/View.'])}
  <div class="grid grid-2 mt-24">${imgCard('query-main')}${imgCard('query-source')}</div>
  ${subhead('SQL mental model (ilustratif; bukan SQL vendor-specific)')}
  <div class="sql-box"><b>SELECT</b> tb.entity_id, tb.period, acc.reporting_line,<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;SUM(tb.amount) AS amount<br><b>FROM</b> fact_tb tb<br><b>LEFT JOIN</b> dim_account acc<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ON tb.account_id = acc.account_id<br><b>WHERE</b> tb.period = :reporting_period<br><b>GROUP BY</b> tb.entity_id, tb.period, acc.reporting_line;</div>
  ${callout('Why LEFT JOIN matters','Jika mapping untuk akun 5999 tidak ditemukan, INNER JOIN dapat menghilangkan baris tersebut dari query dan membuat angka seolah-olah cocok. Dengan LEFT JOIN, akun itu tetap terlihat sebagai NULL / unmapped dan dapat diinvestigasi.')}
  ${subhead('Wdata checks before reporting')}
  <div class="grid grid-2">${doneBox('wd1','Saya tahu perbedaan fact table, dimension table, dan dataset.')}${doneBox('wd2','Saya tahu fungsi schema, grain, tags, dan versioning.')}${doneBox('wd3','Saya bisa menjelaskan left join dan query parameters.')}${doneBox('wd4','Saya mengerti query results harus direkonsiliasi.')}</div>
  <div class="mt-24">${mark('tables')}${mark('queries')}${mark('intro')}${mark('names')}</div></div>`}
function pageChains(){return `<div class="page">${intro(3,'Chains: automate the movement','Chains mengorkestrasi pekerjaan lintas sistem: mulai trigger, command, kondisi, transformasi, load, refresh, sampai monitoring run. Tidak identik dengan workflow approval bisnis.')}
  <div class="grid grid-3"><div class="card card-pad"><span class="pill teal">TRIGGER</span><h3 class="mt-12">When to run?</h3><p>Manual trigger, jadwal, runtime inputs, atau mekanisme lain yang disediakan implementasi. Contoh: closing period.</p></div><div class="card card-pad"><span class="pill violet">COMMAND</span><h3 class="mt-12">What to do?</h3><p>Get file, transform, import dataset, run query, export result, refresh connections, dan tindakan lain via connector.</p></div><div class="card card-pad"><span class="pill orange">FLOW CONTROL</span><h3 class="mt-12">What if it fails?</h3><p>Branch, condition, variable, error action, execution log, retry yang dirancang aman (jangan double load).</p></div></div>
  ${subhead('Core chain anatomy')}
  ${card(`<div class="card-pad"><div class="flow-track">${['Runtime inputs','Extract CSV/API','Validate data','Run Data Prep','Import to Wdata','Run Query','Refresh/Export'].map((x,i)=>`${i?'<div class="flow-chevron">›</div>':''}<div class="flow-stage" style="cursor:default"><span class="number">0${i+1}</span><strong>${x}</strong></div>`).join('')}</div><p class="text-small">Urutan di atas adalah <b>contoh desain</b>, bukan chain template wajib Workiva. Hasil setiap command bisa diteruskan sebagai input command berikutnya.</p></div>`)}
  ${subhead('Connectors, runners & access')}
  <div class="grid grid-2"><div class="card card-pad"><h3>CloudRunner</h3><p>Untuk layanan cloud atau sistem yang dapat diakses secara online. Eksekusi dilakukan melalui infrastruktur Workiva. Koneksi perlu dikonfigurasi dengan autentikasi dan izin yang sesuai.</p><div class="pill teal">CLOUD / SAAS</div></div><div class="card card-pad"><h3>GroundRunner</h3><p>Untuk sumber internal/on-prem/private yang berada di jaringan organisasi. Runner dipasang dan dijalankan pada infrastruktur organisasi untuk mengakses data lokal.</p><div class="pill">ON-PREMISES / PRIVATE</div></div></div>
  <div class="callout warn"><strong>Perizinan tidak boleh dilewati</strong><p>Org Security Admin mengaktifkan connector di tingkat organisasi; Workspace Owner dapat menyiapkan connection sesuai izin. Akses ke Chain Builder umumnya memerlukan role Workspace Owner atau Chain Owner. Gunakan integration user serta OAuth2 grant; rahasiakan client secret.</p></div>
  ${subhead('Hands-on: chain sederhana Run Query → Export')}
  ${numbered(['Siapkan <b>Query</b> yang valid di Wdata serta <b>Spreadsheet</b> sebagai destination. Simpan Query ID dan URL spreadsheet.','Verifikasi <b>Workiva connector</b> telah diaktifkan dan di-setup dengan role dan credentials yang tepat.','Buka <b>Chains → Create → Create Chain</b>; pilih environment yang benar, beri nama unik dan deskripsi.','Di canvas tambahkan trigger <b>Runtime Inputs</b> (misalnya query ID, period, spreadsheet URL).','Tarik Workiva command <b>Run Query</b> ke canvas. Hubungkan dari Start, isi Query ID dan parameters.','Tarik <b>Export Query Result</b>; gunakan <b>Query result ID</b> dari output Run Query serta Spreadsheet URL.','Simpan, validasi, <b>publish</b>, jalankan di environment yang tepat, dan periksa status serta log hasil run.'])}
  <div class="grid grid-2 mt-24">${imgCard('chain-graph')}${imgCard('chain-command')}</div>
  ${subhead('Reusable patterns')}
  <div class="grid grid-2"><div class="card card-pad"><h3>01 · Periodic financial load</h3><p>Scheduled/manual extract → file transform → validate → Wdata table → reconcile. Cocok untuk TB multi-entity.</p></div><div class="card card-pad"><h3>02 · Reporting refresh</h3><p>Run query with period → export to sheet atau refresh incoming connection → verifikasi laporan. Urutan tergantung konfigurasi output.</p></div><div class="card card-pad"><h3>03 · Mapping-driven load</h3><p>Get mapping sheet → Data Prep pipeline → import curated file → cek unmapped → pause/fail bila threshold tidak terpenuhi.</p></div><div class="card card-pad"><h3>04 · Controlled rerun</h3><p>Log batch ID + environment + period → cegah duplicate append → buat exception log → rerun dengan izin dan bukti.</p></div></div>
  ${subhead('Troubleshooting chain run')}
  <div class="table-wrap"><table><thead><tr><th>Symptom</th><th>Possible cause</th><th>First check</th></tr></thead><tbody><tr><td>Authentication / 401 / 403</td><td>OAuth token, grant scope, role, credentials</td><td>Integration user, active grant, object permissions</td></tr><tr><td>Timeout / unreachable host</td><td>Network / runner / source API</td><td>GroundRunner status, network policies, endpoint reachability</td></tr><tr><td>Table schema mismatch</td><td>File kolom atau tipe berubah</td><td>Header, delimiter, decimal, encoding, column ID</td></tr><tr><td>Duplicate loads</td><td>Rerun append tanpa idempotency</td><td>Batch ID, dataset version, load strategy</td></tr><tr><td>Report still stale</td><td>Query/connection tidak di-refresh</td><td>Chain output, refresh timestamp, links/publish</td></tr><tr><td>Refresh conflict</td><td>Refresh yang sama berjalan bersamaan</td><td>Periksa status job; hindari run paralel tak terkontrol</td></tr></tbody></table></div>
  <div class="mt-24">${mark('chains')}${mark('connectors')}${mark('api')}${mark('audits')}${doneBox('ch1','Saya bisa menjelaskan chain, connector, runner, variables, serta membaca kegagalan run.')}</div></div>`}
function pageDataPrep(){return `<div class="page">${intro(4,'Data Prep: clean, map, validate','Data Prep membantu mendefinisikan transformasi yang berulang. Pikirkan sebagai lapisan yang mengubah raw extract dari sistem klien menjadi format yang stabil dan siap dianalisis.')}
  ${callout('Position in architecture','Data Prep tidak wajib pada setiap workflow. Data sederhana dapat langsung dimuat ke Wdata, sedangkan data heterogen sering membutuhkan normalisasi, mapping, dan validasi sebelum downstream queries.')}
  <div class="grid grid-3"><div class="card card-pad"><span class="pill teal">PIPELINES</span><h3 class="mt-12">Transformation steps</h3><p>Aturan yang dijalankan berurutan pada file tabular; contoh rename columns, standardize data types, filter, atau perhitungan.</p></div><div class="card card-pad"><span class="pill violet">SAMPLE DATA</span><h3 class="mt-12">Preview & test</h3><p>Sampel data untuk menguji hasil transformasi dan mapping sebelum menggunakan dataset penuh.</p></div><div class="card card-pad"><span class="pill orange">MAPPING GROUPS</span><h3 class="mt-12">Business classifications</h3><p>Aturan pemetaan kode akun, entity, cost center, atau hierarchy dari struktur sumber ke reporting target.</p></div></div>
  ${subhead('Contoh mapping Chart of Accounts')}
  <div class="table-wrap"><table><thead><tr><th>Source account</th><th>Nama dari ERP</th><th>Target reporting line</th><th>Validation</th></tr></thead><tbody><tr><td class="data-mono">1100</td><td>Bank accounts</td><td>Cash & cash equivalents</td><td><span class="tag-good">Mapped</span></td></tr><tr><td class="data-mono">1200</td><td>Trade receivables</td><td>Trade receivables</td><td><span class="tag-good">Mapped</span></td></tr><tr><td class="data-mono">5100</td><td>Payroll expenses</td><td>Operating expenses</td><td><span class="tag-good">Mapped</span></td></tr><tr><td class="data-mono">5999</td><td>New expense account</td><td>—</td><td><span class="tag-bad">Unmapped</span></td></tr></tbody></table></div>
  ${subhead('Practical validation rules for finance')}
  <div class="grid grid-2"><div class="card card-pad"><h3>Structural checks</h3>${points(['Mandatory columns exist: entity, account, period, currency, amount.','Number/date/decimal formats are valid; consistent thousands separator.','Primary/key grain is understood, duplicate batch detection.','Entity-account keys match approved master data.'])}</div><div class="card card-pad"><h3>Financial checks</h3>${points(['Source/control totals = curated totals (subject to expected adjustments).','Debit/credit sign convention and TB balancing.','All accounts/entities mapped; exceptions documented.','FX translation and intercompany checks only where properly designed.'])}</div></div>
  ${subhead('How pipeline and Chain work together')}
  ${numbered(['Data engineer/analyst mendesain Data Prep <b>pipeline</b> menggunakan sample dataset.','Atur mapping group dan aturan standardisasi; cek output serta exception.','Chain mengekstrak data dari sumber kemudian menjalankan pipeline dengan data input yang sesuai.','Hasil transformasi menjadi file/artefak output Chain; command berikutnya dapat memuatnya ke Wdata atau spreadsheet.','Catat versi mapping, status run, record count dan unmapped entries untuk review.'])}
  ${callout('Audit caution','Mapping group adalah business logic. Perubahan mapping dapat mengubah klasifikasi laporan tanpa mengubah transaksi ERP. Karena itu perlu owner, approval, version, dan impact assessment.','warn')}
  ${subhead('Common transformation anti-patterns')}
  <div class="grid grid-2"><div class="card card-pad"><h3>Silent row loss</h3><p>Inner join ke mapping menyebabkan akun tanpa mapping menghilang. Mitigasi: lakukan left join atau buat exception dataset dan hitung row count.</p></div><div class="card card-pad"><h3>Undocumented correction</h3><p>Menimpa amount agar output sesuai ekspektasi. Mitigasi: setiap perubahan harus melalui source correction atau jurnal adjustment yang disetujui.</p></div></div>
  ${mark('dprep')}${mark('suite')}${mark('learning')}${doneBox('dp1','Saya dapat menjelaskan fungsi pipeline dan mapping group serta risiko unmapped accounts.')}</div>`}
function pageFinance(){return `<div class="page">${intro(5,'Financial reporting & consolidation','Gunakan contoh keuangan yang realistis agar kamu tidak hanya menjelaskan tombol Workiva, tetapi mengapa workflow tersebut berguna untuk tim audit dan financial close.')}
  ${subhead('Use case: multi-entity trial balance')}
  <div class="grid grid-3"><div class="card card-pad"><span class="pill teal">ENTITY A</span><h3 class="mt-12">PT Nusantara Induk</h3><p>Entitas induk (fiktif) menggunakan ERP-A. TB dalam IDR, periode Oktober 2026.</p></div><div class="card card-pad"><span class="pill teal">ENTITY B</span><h3 class="mt-12">PT Cakrawala Niaga</h3><p>Entitas anak (fiktif) menggunakan ERP-B. Struktur account sedikit berbeda dan butuh mapping.</p></div><div class="card card-pad"><span class="pill violet">GROUP</span><h3 class="mt-12">Nusantara Group</h3><p>Data dikumpulkan dan dipetakan ke common reporting COA untuk review laporan keuangan grup.</p></div></div>
  ${subhead('Pemisahan proses yang sering membingungkan')}
  <div class="table-wrap"><table><thead><tr><th>Aktivitas</th><th>Deskripsi</th><th>Umumnya di mana?</th></tr></thead><tbody><tr><td>Data integration</td><td>Mengambil TB/GL dari sumber berbeda</td><td>Chains, API, CSV, Wdata</td></tr><tr><td>Data harmonization</td><td>Normalisasi account/entity/currency labels, format</td><td>Data Prep / Wdata queries</td></tr><tr><td>Reporting aggregation</td><td>Menjumlahkan saldo per reporting line</td><td>Wdata queries/views, Spreadsheet</td></tr><tr><td>Accounting consolidation</td><td>Eliminasi intercompany, FX translation, goodwill/NCI, adjustments</td><td>ERP/EPM atau workflow konsolidasi yang dirancang & dikontrol</td></tr><tr><td>Disclosure/reporting</td><td>Menyusun financial statements & notes yang linked</td><td>Workiva Spreadsheet, Documents, Presentations</td></tr><tr><td>Audit validation</td><td>Tie-out, test completeness/accuracy, sampling, evidence</td><td>Workiva/working papers & prosedur audit tim</td></tr></tbody></table></div>
  ${callout('Workiva is not automatically a consolidation engine','Workiva dapat menjadi sistem connected data/reporting yang mendukung proses konsolidasi. Namun angka konsolidasi yang final harus berasal dari proses yang menerapkan aturan akuntansi yang benar—bukan sekadar SUM seluruh TB perusahaan.')}
  ${subhead('A finance data model')}
  <div class="grid grid-2"><div class="card card-pad"><h3>Fact tables</h3>${points(['<b>F_TB:</b> account, entity, period, currency, source, version, amount.','<b>F_GL:</b> journal_id, posting_date, account, entity, debit, credit, user.','<b>F_ADJUSTMENT:</b> approved journal adjustments, reference, effective period.'])}</div><div class="card card-pad"><h3>Dimensions & mapping</h3>${points(['<b>D_ACCOUNT:</b> source COA → group reporting line.','<b>D_ENTITY:</b> legal entity, parent, country, functional currency.','<b>D_PERIOD:</b> fiscal year, quarter, close status.','<b>D_CURRENCY:</b> currency codes, FX attributes where needed.'])}</div></div>
  ${subhead('Example: auditor-focused reconciliation')}
  <div class="table-wrap"><table><thead><tr><th>Reconciliation layer</th><th>Expected test</th><th>Reason</th></tr></thead><tbody><tr><td>ERP vs extract</td><td>Control total and record count match source</td><td>Completeness</td></tr><tr><td>Extract vs curated dataset</td><td>Same totals after transformations unless approved exceptions</td><td>Accuracy</td></tr><tr><td>TB vs COA mapping</td><td>Unmapped accounts = 0 (or fully resolved)</td><td>Classification</td></tr><tr><td>Prior vs current period</td><td>Material changes explained</td><td>Analytical review</td></tr><tr><td>Consolidated report vs approved consolidation</td><td>FS line items tie to signed-off consolidation</td><td>Reporting integrity</td></tr></tbody></table></div>
  ${subhead('Where audit and finance intersect')}
  <div class="grid grid-3"><div class="card card-pad"><h3>Data completeness</h3><p>Seluruh entitas, periode, buku besar, akun dan transaksi yang relevan harus masuk. Gunakan batch inventory dan control totals.</p></div><div class="card card-pad"><h3>Mapping accuracy</h3><p>Salah mapping akun dapat mengubah klasifikasi FS walau saldo akhir tidak berubah. Review COA dan log perubahan.</p></div><div class="card card-pad"><h3>Audit evidence</h3><p>Catat sumber angka, waktu refresh, versi data, transformasi, exceptions, reviewer, serta dokumentasi prosedur.</p></div></div>
  ${callout('Kerahasiaan klien','Jangan gunakan data client asli dalam demo publik atau rekaman PGL tanpa otorisasi. Gunakan sample dari Workiva atau data sintetis dalam website ini. Hindari screenshot nama client, saldo, kredensial, dan konfigurasi privat.','warn')}
  ${doneBox('fin1','Saya bisa membedakan penggabungan data, reporting rollup, dan accounting consolidation.')}${mark('tables')}${mark('queries')}${mark('datax')}</div>`}
function pageAudit(){return `<div class="page">${intro(6,'Audit-ready data & controls','Tujuan audit data bukan hanya “bisa memindahkan CSV”, melainkan memastikan populasi lengkap, logika transformasi dapat ditelusuri, hasil akurat dan review dapat dibuktikan.')}
  <div class="grid grid-3"><div class="card card-pad"><span class="pill teal">C</span><h3 class="mt-12">Completeness</h3><p>Seluruh baris dan saldo dari source masuk tanpa kehilangan/duplikasi.</p></div><div class="card card-pad"><span class="pill violet">A</span><h3 class="mt-12">Accuracy</h3><p>Nilai, klasifikasi, mata uang dan rumus telah diuji dan diverifikasi.</p></div><div class="card card-pad"><span class="pill orange">T</span><h3 class="mt-12">Traceability</h3><p>Angka dalam laporan dapat dikaitkan ke raw source dan transformasi.</p></div></div>
  ${subhead('Control matrix untuk sebuah TB pipeline')}
  <div class="table-wrap"><table><thead><tr><th>ID</th><th>Control</th><th>Evidence</th><th>Action if failed</th></tr></thead><tbody><tr><td>C-01</td><td>Source extract approved</td><td>File manifest / owner approval</td><td>Reject input</td></tr><tr><td>C-02</td><td>Data type & mandatory columns valid</td><td>Schema validation log</td><td>Fail pipeline</td></tr><tr><td>C-03</td><td>Row count & amount reconcile</td><td>Before/after control totals</td><td>Investigate discrepancy</td></tr><tr><td>C-04</td><td>All mapping keys resolved</td><td>Unmapped exceptions list</td><td>Stop/review mapping</td></tr><tr><td>C-05</td><td>Access least-privilege</td><td>Permissions & grants</td><td>Correct access</td></tr><tr><td>C-06</td><td>Change and publication reviewed</td><td>Version / reviewer sign-off</td><td>Hold final report</td></tr></tbody></table></div>
  ${subhead('Data lineage: how to answer “where did this number come from?”')}
  ${card(`<div class="card-pad"><div class="flow-track">${['ERP GL / TB','Extract batch','Raw Wdata','Mapped query','Connected Sheet','Published Report'].map((x,i)=>`${i?'<span class="flow-chevron">→</span>':''}<div class="flow-stage" style="cursor:default"><span class="number">${String(i+1).padStart(2,'0')}</span><strong>${x}</strong></div>`).join('')}</div><p class="mb-0 text-small">Traceback demo: <b>Revenue FY2026</b> di dokumen → linked spreadsheet cell → Wdata query + filter period → mapping D_ACCOUNT → TB source extract → approved GL. Setiap anak panah harus dapat dibuktikan oleh sistem dan proses tim, bukan diasumsikan.</p></div>`)}
  ${subhead('Governance & permissions')}
  <div class="grid grid-2"><div class="card card-pad"><h3>Access</h3>${points(['Hanya user berwenang yang mengakses data client.','Role dan object permission mempengaruhi aksi di tables, queries, chain.','Integration user memisahkan aksi mesin dari aksi user personal.','Jangan letakkan secrets dalam sheet atau kode frontend.'])}</div><div class="card card-pad"><h3>Trace & monitoring</h3>${points(['Chain Builder menyediakan log aktivitas/audit untuk perubahan chain dan connections.','Catat run ID, status, environment, inputs, dan output version.','Pantau failures, reruns, dan bukti tindakan korektif.','Tanggal update terakhir tidak sama dengan approval.'])}</div></div>
  ${subhead('Audit procedures: practical example')}
  ${numbered(['Minta daftar entitas/periode in-scope dan total saldo resmi dari finance owner.','Ekstrak data via proses yang berizin, lalu simpan manifest dan kontrol jumlah baris.','Uji transformasi dan mapping; keluarkan exception report termasuk akun kosong/tidak dikenal.','Hitung jumlah dan total sebelum/sesudah loading; investigasi setiap selisih yang tidak diharapkan.','Run query untuk populasi audit—misalnya jurnal di akhir periode, unusual account, duplicate entries—sesuai prosedur yang disetujui.','Tie-out hasil query/spreadsheet ke workpaper, lalu dokumentasikan reviewer dan sign-off.'])}
  ${callout('Audit trail ≠ otomatis audited','Pencatatan aktivitas dan source links membantu kontrol, tetapi tidak membuktikan validitas seluruh data. Penilaian desain/efektivitas kontrol, pengujian substantif dan kesimpulan audit tetap memerlukan prosedur serta judgement tim.')}
  ${mark('audits')}${mark('connectors')}${mark('reportVideo')}${doneBox('aud1','Saya mampu menjelaskan 6 kontrol yang diperlukan agar data finance dapat diaudit.')}</div>`}
function pageReporting(){return `<div class="page">${intro(7,'Connected reporting & refresh','Setelah data bersih dan query benar, pekerjaan belum selesai. Nilai harus mengalir secara terkendali ke Spreadsheet, Documents, dan Presentations—dengan refresh serta review yang tepat.')}
  ${subhead('Different connection directions')}
  <div class="grid grid-2"><div class="card card-pad"><span class="pill teal">INCOMING</span><h3 class="mt-12">Wdata query → Spreadsheet</h3><p>Spreadsheet mengonsumsi hasil query dan dapat di-refresh untuk menarik data terbaru. Formula dan laporan yang memakai data ini perlu dicek dampaknya.</p><div class="tip-quote">Contoh: query TB per reporting line → sheet Financial Summary.</div></div><div class="card card-pad"><span class="pill violet">OUTGOING</span><h3 class="mt-12">Spreadsheet → Wdata Table</h3><p>Sheet menjadi sumber connected dataset untuk Wdata table. Cocok untuk update mapping akun/dimensi secara terkontrol, bila pengguna memiliki izin.</p><div class="tip-quote">Contoh: Account Mapping Sheet → D_ACCOUNT table.</div></div></div>
  ${subhead('Standard reporting pipeline')}
  ${numbered(['<b>Wdata Query</b> disimpan dengan parameter period/entity dan lolos validation.','Dalam Workiva Spreadsheet, tambahkan koneksi <b>Incoming → Wdata Query</b> sesuai opsi workspace lalu pilih query dan parameters.','Jalankan <b>Refresh</b> saat source berubah. Periksa timestamp, totals, data yang terkunci oleh connection, dan range yang terdampak.','Gunakan formula/summaries pada spreadsheet; tautkan sumber angka ke <b>Documents/Presentations</b> sesuai workflow linked data.','Refresh connections di dokumen jika digunakan, update/publish linked content sesuai proses, lalu lakukan <b>tie-out</b> dan review akhir.'])}
  ${subhead('Why the final report might still show old figures')}
  <div class="table-wrap"><table><thead><tr><th>Layer</th><th>Updated?</th><th>Possible issue</th></tr></thead><tbody><tr><td>Wdata fact table</td><td><span class="tag-good">Yes</span></td><td>Latest dataset already loaded</td></tr><tr><td>Query result</td><td><span class="tag-good">Yes</span></td><td>Correct period used in query</td></tr><tr><td>Connected Spreadsheet</td><td><span class="tag-bad">No</span></td><td>Incoming connection not refreshed</td></tr><tr><td>Linked Document</td><td><span class="tag-bad">No</span></td><td>Link publication/update or document connection may be pending</td></tr></tbody></table></div>
  ${callout('Refresh is an action, not a guarantee','Jangan menyimpulkan angka pada dokumen final otomatis mutakhir hanya karena Wdata berhasil memuat dataset baru. Periksa rantai koneksi dan status linked data pada setiap layer.')}
  ${subhead('Document-level query connection')}
  <p class="text-small">Workiva mendukung menghubungkan tabel atau chart di Document langsung ke Wdata query melalui <b>Connections panel → Add Connection → Wdata Query</b>. Pengguna dapat mengatur parameters dan melakukan refresh. Permissions pada source dan section menentukan aksi yang diizinkan.</p>
  <div class="grid grid-2">${imgCard('reporting')}${card(`<div class="card-pad"><span class="pill">REVIEW CHECKLIST</span><h3 class="mt-12">Before publication</h3>${points(['Periode, reporting currency dan entity scope benar.','Nilai total untuk setiap significant line sudah tie-out.','Tidak ada query mapping exception yang belum di-review.','Semua connection berhasil refresh, termasuk dependent outputs.','Version, preparer, reviewer dan sign-off tercatat.'])}<div class="mt-24">${doneBox('rep1','Saya bisa menjelaskan incoming/outgoing connections dan mengapa refresh berlapis diperlukan.')}</div></div>`)}</div>
  ${mark('outgoing')}${mark('documents')}${mark('intro')}</div>`}
